  const units=Array.from({length:count},(_,i)=>({id:enemy.id,name:enemy.name+(i?' · support '+i:''),type:enemy.type,level:Math.max(1,level-(i?2:0)),hp:100,break:i===0?gauge:0,normalizedHp:true}));
  return {kind:'labyrinth',id:floor+'-'+step,name:roomType+' · '+enemy.name,power:null,waves:1,sub:difficulty+' · Floor '+floor+' · Room '+step,key:'Labyrinth/'+difficulty+'/'+floor+'/'+step,return:'labyrinth-map',cost:0,units,difficulty,roomType,floor,step,normalizedHp:true}
