 if(p.kind==='challenge'){const x=c.data.challenges.find(x=>x.id===p.id);if(!x)return {unsupported:true,kind:'challenge',name:'Unknown challenge',return:'challenges',waves:0,cost:0};return {kind:p.kind,id:x.id,name:x.name,power:x.power,waves:1,sub:x.kind==='Material'?'Designated farm · '+x.cost+' farm energy':x.kind+' · '+x.dailyLimit+' daily attempts',key:'Challenge/'+x.id,return:'challenges',cost:x.kind==='Material'?x.cost:0,feature:'challenges',dailyLimit:x.dailyLimit}}
 if(p.kind==='tower'){const x=c.data.tower.find(x=>x.floor===p.floor);if(!x)return {unsupported:true,kind:'tower',name:'Unknown Tower floor',return:'tower',waves:0,cost:0};return {kind:p.kind,id:x.floor,name:x.name,power:x.power,waves:x.waves,sub:'One-time ascent · Floor '+x.floor,key:'Tower/'+x.floor,return:'tower',cost:0,feature:'tower'}}
