 const s=source,enc=pending(c),final=s.wave>=Math.max(1,enc.waves),defeat=s.result==='Defeat',retreated=s.retreated||s.result==='Retreated',inProgress=!final&&!defeat&&!retreated,victory=final&&!defeat&&!retreated,r=rewardProjection(c,enc);
