 if(a.labPendingCombat&&a.labEncounterContext){const snap=a.labEncounterContext,key=snap.floor+'/'+snap.step+'/'+snap.roomType;if(s.activeLabKey!==key){s.activeLabKey=key;s.activeBattle=true;s.activeEncounter=null;s.partyHp={};(snap.party||c.data.party).forEach((id,i)=>s.partyHp[id]=Math.max(0,Math.min(1,(snap.hpRatios||a.labHP||[])[i]??.84)));const ids=snap.party||c.data.party,grid=s.formation.map(id=>ids.includes(id)?id:null);ids.filter(id=>!grid.includes(id)).forEach(id=>{const empty=grid.indexOf(null);if(empty>=0)grid[empty]=id});s.frozen=grid;s.wave=1;s.enemyDamage={};s.breakDamage={};s.resultApplied=false;s.retreated=false;s.result='Victory';s.turns=1;s.log=['Entered the Labyrinth room.','Existing injuries, defeats and assigned cells retained.'];if(hpRatio(c,s.battleHero)<=0)s.battleHero=ids.find(id=>hpRatio(c,id)>0)||ids[0]}}
