   if(enc.kind==='labyrinth'&&a.labPendingCombat){const snap=a.labEncounterContext;const ids=snap?.party||c.data.party;a.labHP=ids.map(id=>hpRatio(c,id));s.resultApplied=true;s.activeBattle=false;s.pendingEncounter=null;s.activeEncounter=null;s.resultReturn=(!victory||a.labHP.every(x=>x<=0))?'labyrinth-failed':a.labCombatReturn||'labyrinth-map';const api=window.InterfaceModules.adventures;if(api?.action)api.action('lab-combat-resolve',{outcome:victory?'victory':'defeat',turns:s.turns},c);else c.route('labyrinth-map');s.frozen=null;break}
