      s.campaignXp+=Number(r.unitXp||0);s.campaignClaims[(enc.difficulty||s.difficulty)+'/'+enc.id]=true;
      if(enc.difficulty==='Hard')s.hardProgress=Math.max(s.hardProgress,enc.id+1);
